      "concept_name": {
        "text": "Human oversight for toxicity detection",
        "refs": ["Q0000"],
        "claims": [
          {
            "text": "Peter monitors Buddy's outputs to identify toxic versus non‑toxic responses.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
