      },
      "content": {
        "text": "Buddy can produce multiple answers to the same question, and Peter labels each as toxic or not.",
        "refs": ["Q0001"],
        "claims": [
          {
            "text": "Multiple candidate answers are generated and a human annotator determines which are toxic.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
