      "concept_name": {
        "text": "Training eliminates toxic language",
        "refs": ["Q0002"],
        "claims": [
          {
            "text": "After the labeling and training process, Buddy no longer uses toxic language.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "corrected_approach",
            "refs": ["Q0002"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "OpenAI applied a similar human‑in‑the‑loop approach (RLHF) to make ChatGPT less toxic.",
        "refs": ["Q0003", "Q0004"],
        "claims": [
          {
            "text": "OpenAI used large‑scale human feedback (RLHF) to reduce toxicity in ChatGPT.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0003", "Q0004"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "LLMs lack subjective experience",
        "refs": ["Q0005"],
        "claims": [
          {
            "text": "Large language models do not possess emotions, consciousness, or subjective experience.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0005"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "LLMs operate purely on the data they were trained on.",
        "refs": ["Q0006"],
        "claims": [
          {
            "text": "LLM behavior is determined solely by training data, not by internal feelings.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0006"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Retrieval‑Augmented Generation (RAG)",
        "refs": ["Q0010", "Q0011"],
        "claims": [
          {
            "text": "RAG combines an LLM with external knowledge sources (e.g., PDFs) to answer questions about private data.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "alternative_valid_approach",
            "refs": ["Q0010", "Q0011"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "A custom chatbot can be built for a private company by using any LLM (Claude, GPT) together with retrieval‑augmented generation.",
        "refs": ["Q0010", "Q0011"],
        "claims": [
          {
            "text": "LLM can be connected to a retrieval system that accesses private documents to answer queries.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0010", "Q0011"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "LLM as tool‑using agent via APIs",
        "refs": ["Q0014", "Q0015", "Q0016"],
        "claims": [
          {
            "text": "LLM can be given access to external APIs (e.g., HR management system) and invoke them to perform actions like checking leave balance or applying for leave.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0014", "Q0015", "Q0016"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "When a user asks about their remaining leave, the LLM uses the provided API to look up the employee record and can also submit a leave request.",
        "refs": ["Q0016"],
        "claims": [
          {
            "text": "LLM can retrieve user‑specific data via an API and act on it (e.g., apply for leave).",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0016"],
